import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
    Box,
    Typography,
    Grid,
    Card,
    CardContent,
    Button,
    TextField,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Chip,
    Alert,
    CircularProgress,
    Tab,
    Tabs,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Divider,
    Link,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
    TrendingUp,
    ShoppingCart,
    AccountBalance,
    History,
    Add,
    Remove,
    SwapHoriz,
    Nature,
} from '@mui/icons-material';
import { Link as RouterLink, useSearchParams } from 'react-router-dom';
import {
    ComposedChart,
    Line,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Legend,
    ResponsiveContainer,
} from 'recharts';
import {
    axisTickForMode,
    cartesianGridStroke,
    chartAnimationProps,
    rechartsLegendProps,
    rechartsTooltipProps,
} from '../theme/rechartsAppearances';
import api from '../services/api';
import TabSectionNavLinks from './TabSectionNavLinks';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import IndianCarbonMarketPanel, { type IcmIntegrationConfig } from './icm/IndianCarbonMarketPanel';
import { useUrlTabParam } from '../hooks/useUrlTabParam';

const CARBON_MARKETPLACE_TAB_LABELS = [
    'Offset projects',
    'Credits wallet',
    'Market trends',
    'Trade history',
] as const;

type RequestStatus = 'loading' | 'ready' | 'error';
type HistoryStatus = 'idle' | 'loading' | 'ready' | 'error';

const confirmedTons = (status: RequestStatus, value: number): string => {
    if (status === 'loading') return '…';
    if (status !== 'ready') return 'Unavailable';
    return `${value.toFixed(2)} t`;
};

const requestFailureText = (label: string, err: unknown): string => {
    const detail = err instanceof Error && err.message ? err.message : 'Request failed';
    return `${label} ${detail}`;
};

type RetireCreditSource = 'purchased' | 'earned';

interface MarketListing {
    _id: string;
    seller?: string;
    name?: string;
    credits: number;
    pricePerCredit: number;
    totalValue?: number;
    availableCredits?: number;
    status: string;
    verifiedBy?: string;
    icmRegistered?: boolean;
    icmProjectId?: string;
    icmPortalProjectUrl?: string;
    creditInstrument?: string;
    location?: {
        city?: string;
        state?: string;
        country?: string;
    };
    createdAt?: string;
}

interface UnifiedTradeRow {
    _id: string;
    source: 'offset' | 'pool';
    type: string;
    credits: number;
    pricePerCredit: number;
    totalAmount: number;
    status: string;
    createdAt: string;
    label?: string;
}

interface WalletSnapshot {
    purchasedAvailable: number;
    purchasedTotal: number;
    purchasedRetired: number;
    purchasedAvgPrice: number;
    earnedAvailable: number;
    earnedAllocated: number;
    earnedRetired: number;
    poolPricePerCredit: number;
}

const CarbonTrading: React.FC<{ embedded?: boolean }> = ({ embedded = false }) => {
    const theme = useTheme();
    const isDark = theme.palette.mode === 'dark';
    const gridStroke = cartesianGridStroke(isDark);
    const tickStyle = axisTickForMode(isDark);
    const tipProps = rechartsTooltipProps(isDark);
  const [searchParams] = useSearchParams();
    const [tabValue, setTabValue] = useUrlTabParam(0, { maxTab: CARBON_MARKETPLACE_TAB_LABELS.length - 1 });
    const [loading, setLoading] = useState(false);
    const [listingsStatus, setListingsStatus] = useState<RequestStatus>('loading');
    const [listingsError, setListingsError] = useState<string | null>(null);
    const [portfolioStatus, setPortfolioStatus] = useState<RequestStatus>('loading');
    const [earnedStatus, setEarnedStatus] = useState<RequestStatus>('loading');
    const [poolPriceStatus, setPoolPriceStatus] = useState<RequestStatus>('loading');
    const [walletError, setWalletError] = useState<string | null>(null);
    const [historyStatus, setHistoryStatus] = useState<HistoryStatus>('idle');
    const [historyError, setHistoryError] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    const [wallet, setWallet] = useState<WalletSnapshot>({
        purchasedAvailable: 0,
        purchasedTotal: 0,
        purchasedRetired: 0,
        purchasedAvgPrice: 0,
        earnedAvailable: 0,
        earnedAllocated: 0,
        earnedRetired: 0,
        poolPricePerCredit: 0,
    });
    const [tradeHistory, setTradeHistory] = useState<UnifiedTradeRow[]>([]);
    const [marketListings, setMarketListings] = useState<MarketListing[]>([]);
    const [priceHistory, setPriceHistory] = useState<{ date: string; price: number }[]>([]);
    const [footprintTons, setFootprintTons] = useState<number | null>(null);

    const [buyDialogOpen, setBuyDialogOpen] = useState(false);
    const [retireDialogOpen, setRetireDialogOpen] = useState(false);
    const [transferDialogOpen, setTransferDialogOpen] = useState(false);
    const [selectedListing, setSelectedListing] = useState<MarketListing | null>(null);

    const [buyAmount, setBuyAmount] = useState('');
    const [retireAmount, setRetireAmount] = useState('');
    const [retireSource, setRetireSource] = useState<RetireCreditSource>('purchased');
    const [retireReason, setRetireReason] = useState('');
    const [transferAmount, setTransferAmount] = useState('');
    const [transferRecipientId, setTransferRecipientId] = useState('');
    const [transferDescription, setTransferDescription] = useState('');
    const [icmIntegration, setIcmIntegration] = useState<IcmIntegrationConfig | null>(null);

    const suggestedOffsetTons = useMemo(() => {
        const fromQuery = Number(searchParams.get('offsetTons'));
        if (Number.isFinite(fromQuery) && fromQuery > 0) {
            return fromQuery;
        }
        return null;
    }, [searchParams]);

    const balancesConfirmed = portfolioStatus === 'ready' && earnedStatus === 'ready';
    const totalAvailableCredits = balancesConfirmed
        ? wallet.purchasedAvailable + wallet.earnedAvailable
        : null;
    const canRetirePurchased = portfolioStatus === 'ready' && wallet.purchasedAvailable > 0;
    const canRetireEarned = earnedStatus === 'ready' && wallet.earnedAvailable > 0;

    const loadFootprintSuggestion = useCallback(async () => {
        if (suggestedOffsetTons != null) {
            setFootprintTons(suggestedOffsetTons);
            return;
        }
        try {
            const stats = await api.getMSMEStats() as {
              data?: {
                carbon?: {
                  totalCO2Emissions?: number;
                  esgScopes?: {
                    scope1?: { total?: number };
                    scope2?: { total?: number };
                    scope3?: { total?: number };
                  };
                };
              };
            };
            const kg = Number(stats?.data?.carbon?.totalCO2Emissions);
            const scopes = stats?.data?.carbon?.esgScopes;
            const scopeSum = (Number(scopes?.scope1?.total) || 0)
              + (Number(scopes?.scope2?.total) || 0)
              + (Number(scopes?.scope3?.total) || 0);
            const reconciled = (() => {
              const raw = Number.isFinite(kg) && kg > 0 ? kg : 0;
              if (scopeSum <= 0) return raw;
              if (!raw) return scopeSum;
              if (raw / scopeSum > 1.5 || scopeSum / raw > 1.5) return scopeSum;
              return raw;
            })();
            if (reconciled > 0) {
                setFootprintTons(Number((reconciled / 1000).toFixed(3)));
            }
        } catch {
            // optional enrichment
        }
    }, [suggestedOffsetTons]);

    const fetchWallet = useCallback(async () => {
        setPortfolioStatus('loading');
        setEarnedStatus('loading');
        setPoolPriceStatus('loading');
        setWalletError(null);

        const [portfolioResult, earnedResult, marketResult] = await Promise.all([
            api.getCarbonTradingPortfolio().then(
                (res) => ({ ok: true as const, res }),
                (err: unknown) => ({ ok: false as const, err })
            ),
            api.getMyCarbonPoolCredits().then(
                (res) => ({ ok: true as const, res }),
                (err: unknown) => ({ ok: false as const, err })
            ),
            api.getCarbonCreditsMarket().then(
                (res) => ({ ok: true as const, res }),
                (err: unknown) => ({ ok: false as const, err })
            ),
        ]);

        const failures: string[] = [];

        if (portfolioResult.ok) {
            const portfolio = portfolioResult.res?.data;
            setWallet((prev) => ({
                ...prev,
                purchasedAvailable: Number(portfolio?.availableCredits ?? 0),
                purchasedTotal: Number(portfolio?.totalCredits ?? 0),
                purchasedRetired: Number(portfolio?.usedCredits ?? 0),
                purchasedAvgPrice: Number(portfolio?.averagePrice ?? 0),
            }));
            setPortfolioStatus('ready');
        } else {
            setPortfolioStatus('error');
            failures.push(requestFailureText('Purchased credits could not be loaded.', portfolioResult.err));
        }

        if (earnedResult.ok) {
            const earned = earnedResult.res?.data;
            setWallet((prev) => ({
                ...prev,
                earnedAvailable: Number(earned?.availableCredits ?? 0),
                earnedAllocated: Number(earned?.allocatedCredits ?? 0),
                earnedRetired: Number(earned?.retiredCredits ?? 0),
            }));
            setEarnedStatus('ready');
        } else {
            setEarnedStatus('error');
            failures.push(requestFailureText('Earned credits could not be loaded.', earnedResult.err));
        }

        if (marketResult.ok) {
            const market = marketResult.res?.data;
            const poolPrice = Number(
                market?.pool?.currentPricePerCredit
                ?? market?.marketMetrics?.averagePrice
                ?? 0
            );
            setWallet((prev) => ({
                ...prev,
                poolPricePerCredit: poolPrice,
            }));
            setPoolPriceStatus('ready');
        } else {
            setPoolPriceStatus('error');
            failures.push(requestFailureText('Pool price could not be loaded.', marketResult.err));
        }

        setWalletError(failures.length > 0 ? failures.join(' ') : null);
    }, []);

    const fetchTradeHistory = useCallback(async () => {
        setHistoryStatus('loading');
        setHistoryError(null);

        const [offsetResult, poolResult] = await Promise.all([
            api.getCarbonTradingHistory({ limit: 50 }).then(
                (res) => ({ ok: true as const, res }),
                (err: unknown) => ({ ok: false as const, err })
            ),
            api.getCarbonCreditsTransactions({ limit: 50 }).then(
                (res) => ({ ok: true as const, res }),
                (err: unknown) => ({ ok: false as const, err })
            ),
        ]);

        const offsetHistory = offsetResult.ok ? offsetResult.res : undefined;
        const poolHistory = poolResult.ok ? poolResult.res : undefined;
        const failures: string[] = [];
        if (!offsetResult.ok) {
            failures.push(requestFailureText('Offset history could not be loaded.', offsetResult.err));
        }
        if (!poolResult.ok) {
            failures.push(requestFailureText('Pool history could not be loaded.', poolResult.err));
        }

        const offsetRows: UnifiedTradeRow[] = (offsetHistory?.data?.transactions || []).map((entry: {
            _id?: string;
            type?: string;
            amount?: number;
            pricePerTon?: number;
            totalCost?: number;
            status?: string;
            timestamp?: string;
            offsetName?: string;
        }) => ({
            _id: entry._id || `offset_${entry.timestamp}`,
            source: 'offset' as const,
            type: entry.type || 'purchase',
            credits: Number(entry.amount || 0),
            pricePerCredit: Number(entry.pricePerTon || 0),
            totalAmount: Number(entry.totalCost || 0),
            status: entry.status || 'completed',
            createdAt: entry.timestamp || new Date().toISOString(),
            label: entry.offsetName,
        }));

        const poolRows: UnifiedTradeRow[] = (poolHistory?.data?.transactions || []).map((entry: {
            _id?: string;
            type?: string;
            creditsAmount?: number;
            pricePerCredit?: number;
            totalValue?: number;
            status?: string;
            createdAt?: string;
            description?: string;
        }) => ({
            _id: entry._id || `pool_${entry.createdAt}`,
            source: 'pool' as const,
            type: entry.type || 'allocation',
            credits: Number(entry.creditsAmount || 0),
            pricePerCredit: Number(entry.pricePerCredit || 0),
            totalAmount: Number(entry.totalValue || 0),
            status: entry.status || 'completed',
            createdAt: entry.createdAt || new Date().toISOString(),
            label: entry.description,
        }));

        const merged = [...offsetRows, ...poolRows].sort(
            (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        );
        setTradeHistory(merged);
        setHistoryError(failures.length > 0 ? failures.join(' ') : null);
        setHistoryStatus(failures.length > 0 ? 'error' : 'ready');
    }, []);

    const fetchIcmIntegration = useCallback(async () => {
        try {
            const res = await api.getIndianCarbonMarketIntegration();
            setIcmIntegration((res?.data as IcmIntegrationConfig) ?? null);
        } catch {
            setIcmIntegration(null);
    }
  }, []);

    const fetchMarketListings = useCallback(async () => {
        setListingsStatus('loading');
        setListingsError(null);
        let response: Awaited<ReturnType<typeof api.getCarbonOffsetOptions>> | undefined;
        try {
            response = await api.getCarbonOffsetOptions({ limit: 100 });
        } catch (err: unknown) {
            setMarketListings([]);
            setPriceHistory([]);
            setListingsStatus('error');
            setListingsError(err instanceof Error ? err.message : 'Failed to load offset projects');
            return;
        }
        const rawListings = response?.data || [];
        const normalizedListings: MarketListing[] = rawListings.map((listing: {
            _id: string;
            name?: string;
            availableCredits?: number;
            pricePerTon?: number;
            verifiedBy?: string;
            isActive?: boolean;
            location?: MarketListing['location'] | string;
            createdAt?: string;
            icmRegistry?: {
                isRegistered?: boolean;
                projectId?: string;
                portalProjectUrl?: string;
                creditInstrument?: string;
            };
        }) => ({
            _id: listing._id,
            seller: listing.verifiedBy || 'Verified registry',
            name: listing.name,
            credits: Number(listing.availableCredits || 0),
            availableCredits: Number(listing.availableCredits || 0),
            pricePerCredit: Number(listing.pricePerTon || 0),
            totalValue: Number((listing.availableCredits || 0) * (listing.pricePerTon || 0)),
            status: listing.isActive ? 'active' : 'inactive',
            verifiedBy: listing.verifiedBy,
            icmRegistered: Boolean(listing.icmRegistry?.isRegistered),
            icmProjectId: listing.icmRegistry?.projectId,
            icmPortalProjectUrl: listing.icmRegistry?.portalProjectUrl,
            creditInstrument: listing.icmRegistry?.creditInstrument,
            location: typeof listing.location === 'string' ? { city: listing.location } : listing.location,
            createdAt: listing.createdAt,
        }));
        setMarketListings(normalizedListings);

        const grouped = rawListings.reduce((acc: Record<string, { total: number; count: number }>, listing: {
            createdAt?: string;
            pricePerTon?: number;
        }) => {
            const date = new Date(listing.createdAt || Date.now()).toISOString().slice(0, 10);
            if (!acc[date]) {
                acc[date] = { total: 0, count: 0 };
            }
            acc[date].total += Number(listing.pricePerTon || 0);
            acc[date].count += 1;
            return acc;
        }, {});
        const chartData = Object.entries(grouped)
            .sort((a, b) => a[0].localeCompare(b[0]))
            .map(([date, metrics]) => ({
                date,
                price: Number((metrics.total / Math.max(metrics.count, 1)).toFixed(2)),
            }));
        setPriceHistory(chartData);
        setListingsStatus('ready');
        setListingsError(null);
    }, []);

    const refreshAll = useCallback(async () => {
        setError(null);
        await Promise.all([
            fetchMarketListings(),
            fetchWallet(),
            fetchIcmIntegration(),
            loadFootprintSuggestion(),
        ]);
    }, [fetchWallet, fetchMarketListings, fetchIcmIntegration, loadFootprintSuggestion]);

    useEffect(() => {
        refreshAll();
    }, [refreshAll]);

    // Trade history is only rendered on the History tab — load on demand.
  useEffect(() => {
        if (tabValue === 3) {
            void fetchTradeHistory();
        }
    }, [tabValue, fetchTradeHistory]);

    const openRetireWithSuggestion = () => {
        if (footprintTons != null && footprintTons > 0) {
            setRetireAmount(String(footprintTons));
            setRetireReason('Offset assessed carbon footprint');
        }
        setRetireDialogOpen(true);
    };

    const handleBuyCredits = async () => {
        if (!selectedListing || !buyAmount) return;

        try {
            setLoading(true);
            setError(null);
            await api.purchaseCarbonOffset({
                offsetId: selectedListing._id,
                amount: Number(buyAmount),
                pricePerTon: selectedListing.pricePerCredit,
            });
            setSuccess('Successfully purchased offset credits from project catalog.');
            setBuyDialogOpen(false);
            setBuyAmount('');
            setSelectedListing(null);
            await refreshAll();
        } catch (err: unknown) {
            setError(err instanceof Error ? err.message : 'Failed to buy credits');
        } finally {
            setLoading(false);
        }
    };

    const handleRetireCredits = async () => {
        if (!retireAmount) return;
        const amount = Number(retireAmount);
        if (!Number.isFinite(amount) || amount <= 0) return;

        const sourceReady = retireSource === 'purchased' ? portfolioStatus === 'ready' : earnedStatus === 'ready';
        if (!sourceReady) {
            setError('That credit balance could not be confirmed. Refresh the page before retiring.');
            return;
        }
        const maxForSource = retireSource === 'purchased' ? wallet.purchasedAvailable : wallet.earnedAvailable;
        if (amount > maxForSource) {
            setError(`Insufficient ${retireSource === 'purchased' ? 'purchased' : 'earned'} credits. Available: ${maxForSource.toFixed(2)}`);
            return;
        }

        try {
            setLoading(true);
            setError(null);
            if (retireSource === 'purchased') {
                await api.offsetCarbonCredits({
                    amount,
                    description: retireReason || 'Credits retired against emissions footprint',
                });
            } else {
                await api.retirePoolCarbonCredits({
                    amount,
                    reason: retireReason || 'Voluntary retirement of earned pool credits',
                });
            }
            setSuccess('Credits retired successfully.');
            setRetireDialogOpen(false);
            setRetireAmount('');
            setRetireReason('');
            await refreshAll();
        } catch (err: unknown) {
            setError(err instanceof Error ? err.message : 'Failed to retire credits');
        } finally {
            setLoading(false);
        }
    };

    const handleTransferCredits = async () => {
        if (!transferAmount || !transferRecipientId) return;

        try {
            setLoading(true);
            setError(null);
            await api.transferPoolCarbonCredits({
                toMSMEId: transferRecipientId.trim(),
                amount: Number(transferAmount),
                description: transferDescription || 'Transfer via carbon marketplace',
            });
            setSuccess('Earned pool credits transferred successfully.');
            setTransferDialogOpen(false);
            setTransferAmount('');
            setTransferRecipientId('');
            setTransferDescription('');
            await refreshAll();
        } catch (err: unknown) {
            setError(err instanceof Error ? err.message : 'Failed to transfer credits');
        } finally {
            setLoading(false);
        }
    };

    const openBuyDialog = (listing: MarketListing) => {
        setSelectedListing(listing);
        setBuyDialogOpen(true);
    };

    const formatLocation = (location?: MarketListing['location']) => {
        if (!location) return '—';
        return [location.city, location.state, location.country].filter(Boolean).join(', ') || '—';
    };

    return (
      <Box>
        {!embedded ? (
            <WorkspacePageHeader
                title="Offsets and credits"
                description="Browse verified offset projects, manage earned Indian Carbon Market pool credits, and retire credits against your footprint."
            />
        ) : null}
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                Official registry and MSME programmes are on{' '}
                <Link href="https://indiancarbonmarket.gov.in" target="_blank" rel="noopener noreferrer">
                    indiancarbonmarket.gov.in
                </Link>
                .
            </Typography>

            <IndianCarbonMarketPanel integration={icmIntegration} />

            {footprintTons != null && footprintTons > 0 && (
                <Alert
                    severity="info"
                    icon={<Nature />}
                    sx={{
                        mb: 2,
                        alignItems: 'flex-start',
                        flexWrap: 'wrap',
                        '& .MuiAlert-message': { flex: '1 1 16rem', minWidth: 0 },
                        '& .MuiAlert-action': {
                            flex: '1 1 auto',
                            marginLeft: { xs: 0, sm: 'auto' },
                            paddingLeft: { xs: 0, sm: 2 },
                            paddingTop: { xs: 1, sm: 0 },
                            alignItems: 'center',
                        },
                    }}
                    action={(
                        <Button
                            color="inherit"
                            size="small"
                            onClick={openRetireWithSuggestion}
                            disabled={!balancesConfirmed || (totalAvailableCredits ?? 0) <= 0}
                            sx={{ whiteSpace: 'nowrap' }}
                        >
                            {`Retire ${footprintTons.toFixed(3)}\u00a0t`}
                        </Button>
                    )}
                >
                    Based on your latest footprint data, you may offset about{' '}
                    <strong>{footprintTons.toFixed(3)} t CO₂e</strong> (credit tons are modeled 1:1 with tonnes retired).
                    {balancesConfirmed && (totalAvailableCredits ?? 0) <= 0
                        ? ' Purchase or earn credits before retiring against this footprint.'
                        : null}
                </Alert>
            )}

            {walletError && (
                <Alert severity="error" onClose={() => setWalletError(null)} sx={{ mb: 2 }}>
                    {walletError}
                </Alert>
            )}
            {error && (
                <Alert severity="error" onClose={() => setError(null)} sx={{ mb: 2 }}>
                    {error}
                </Alert>
            )}
            {success && (
                <Alert severity="success" onClose={() => setSuccess(null)} sx={{ mb: 2 }}>
                    {success}
                </Alert>
            )}

            <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                <AccountBalance color="primary" sx={{ mr: 1 }} />
                                <Typography variant="h6">Total available</Typography>
                            </Box>
                            <Typography variant="h4" fontWeight="bold" sx={{ whiteSpace: 'nowrap' }}>
                                {confirmedTons(
                                    portfolioStatus === 'loading' || earnedStatus === 'loading'
                                        ? 'loading'
                                        : balancesConfirmed ? 'ready' : 'error',
                                    totalAvailableCredits ?? 0
                                )}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                                Purchased + earned pool credits
                            </Typography>
            </CardContent>
          </Card>
                </Grid>
                <Grid item xs={12} md={3}>
        <Card>
          <CardContent>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                <ShoppingCart color="success" sx={{ mr: 1 }} />
                                <Typography variant="h6">Purchased offsets</Typography>
                            </Box>
                            <Typography variant="h4" fontWeight="bold" color="success.main" sx={{ whiteSpace: 'nowrap' }}>
                                {confirmedTons(portfolioStatus, wallet.purchasedAvailable)}
                            </Typography>
                            <Typography variant="caption" color="text.secondary" sx={{ whiteSpace: 'nowrap' }}>
                                {portfolioStatus === 'ready'
                                    ? `From verified projects · avg $${wallet.purchasedAvgPrice.toFixed(2)}/t`
                                    : portfolioStatus === 'error'
                                        ? 'Purchased credits unavailable'
                                        : 'Loading purchased credits'}
                            </Typography>
          </CardContent>
        </Card>
                </Grid>
                <Grid item xs={12} md={3}>
        <Card>
          <CardContent>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                <TrendingUp color="info" sx={{ mr: 1 }} />
                                <Typography variant="h6">Earned (ICM pool)</Typography>
                            </Box>
                            <Typography variant="h4" fontWeight="bold" color="info.main" sx={{ whiteSpace: 'nowrap' }}>
                                {confirmedTons(earnedStatus, wallet.earnedAvailable)}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                                {earnedStatus === 'ready'
                                    ? `Allocated ${wallet.earnedAllocated.toFixed(2)} t${
                                        poolPriceStatus === 'ready'
                                            ? ` · pool ~$${wallet.poolPricePerCredit.toFixed(2)}/credit`
                                            : poolPriceStatus === 'error'
                                                ? ' · pool price unavailable'
                                                : ''
                                    }`
                                    : earnedStatus === 'error'
                                        ? 'Earned credits unavailable'
                                        : 'Loading earned credits'}
                            </Typography>
          </CardContent>
        </Card>
                </Grid>
                <Grid item xs={12} md={3}>
      <Card>
        <CardContent>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                <Remove color="error" sx={{ mr: 1 }} />
                                <Typography variant="h6">Retired</Typography>
                            </Box>
                            <Typography variant="h4" fontWeight="bold" color="error.main" sx={{ whiteSpace: 'nowrap' }}>
                                {confirmedTons(
                                    portfolioStatus === 'loading' || earnedStatus === 'loading'
                                        ? 'loading'
                                        : balancesConfirmed ? 'ready' : 'error',
                                    (wallet.purchasedRetired + wallet.earnedRetired)
                                )}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                                Purchased {confirmedTons(portfolioStatus, wallet.purchasedRetired)} · earned {confirmedTons(earnedStatus, wallet.earnedRetired)}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            <Box sx={{ mb: 4, display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center' }}>
                <Button
                    variant="contained"
                    color="primary"
                    startIcon={<Add />}
                    onClick={() => {
                        setTabValue(0);
                        if (marketListings.length > 0) {
                            openBuyDialog(marketListings[0]);
                        }
                    }}
                    disabled={loading || listingsStatus !== 'ready' || marketListings.length === 0}
                    aria-describedby={listingsStatus === 'ready' && marketListings.length === 0 ? 'buy-from-projects-reason' : undefined}
                >
                    Buy from projects
                </Button>
                {listingsStatus === 'ready' && marketListings.length === 0 && (
                    <Typography id="buy-from-projects-reason" variant="body2" color="text.secondary">
                        No projects in the catalog.
                    </Typography>
                )}
                <Button
                    variant="outlined"
                    color="primary"
                    startIcon={<Remove />}
                    onClick={() => {
                        if (!canRetirePurchased && canRetireEarned) {
                            setRetireSource('earned');
                        }
                        setRetireDialogOpen(true);
                    }}
                    disabled={loading || (!canRetirePurchased && !canRetireEarned)}
                >
                    Retire credits
                </Button>
                    <Button
                      variant="outlined"
                    startIcon={<SwapHoriz />}
                    onClick={() => setTransferDialogOpen(true)}
                    disabled={loading || earnedStatus !== 'ready' || wallet.earnedAvailable <= 0}
                    >
                    Transfer earned credits
                </Button>
                <Button component={RouterLink} to="/carbon-footprint?section=assessment-results" variant="text">
                    View footprint assessment
                    </Button>
            </Box>

            <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
                <Tabs
                    value={tabValue}
                    onChange={(_e, newValue) => setTabValue(newValue)}
                    variant="scrollable"
                    scrollButtons="auto"
                    allowScrollButtonsMobile
                    aria-label="Offsets and credits sections"
                >
                    <Tab label="Offset projects" id="carbon-marketplace-tab-0" aria-controls="carbon-marketplace-panel-0" icon={<ShoppingCart />} iconPosition="start" />
                    <Tab label="Credits wallet" id="carbon-marketplace-tab-1" aria-controls="carbon-marketplace-panel-1" icon={<AccountBalance />} iconPosition="start" />
                    <Tab label="Market trends" id="carbon-marketplace-tab-2" aria-controls="carbon-marketplace-panel-2" icon={<TrendingUp />} iconPosition="start" />
                    <Tab label="Trade history" id="carbon-marketplace-tab-3" aria-controls="carbon-marketplace-panel-3" icon={<History />} iconPosition="start" />
                </Tabs>
                <TabSectionNavLinks
                    tabLabels={[...CARBON_MARKETPLACE_TAB_LABELS]}
                    currentIndex={tabValue}
                    onNavigate={setTabValue}
                />
              </Box>

            <Box
                role="tabpanel"
                id="carbon-marketplace-panel-0"
                aria-labelledby="carbon-marketplace-tab-0"
                hidden={tabValue !== 0}
            >
            {tabValue === 0 && (
                <Card>
                    <CardContent>
                        <Typography variant="h6" gutterBottom>
                            Verified offset projects
                        </Typography>
                        {listingsStatus === 'loading' ? (
                            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                                <CircularProgress aria-label="Loading offset projects" />
                            </Box>
                        ) : listingsStatus === 'error' ? (
                            <Alert severity="error">
                                {listingsError || 'Offset projects could not be loaded.'}
                            </Alert>
                        ) : (
                            <TableContainer>
                                <Table>
                                    <TableHead>
                                        <TableRow>
                                            <TableCell>Registry</TableCell>
                                            <TableCell>Project</TableCell>
                                            <TableCell>Location</TableCell>
                                            <TableCell align="right">Available (t)</TableCell>
                                            <TableCell align="right">Price/t</TableCell>
                                            <TableCell>Status</TableCell>
                                            <TableCell align="right">Action</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {marketListings.length === 0 ? (
                                            <TableRow>
                                                <TableCell colSpan={7} align="center">
                                                    No offset projects in catalog. Contact your administrator to seed projects.
                                                </TableCell>
                                            </TableRow>
                                        ) : (
                                            marketListings.map((listing) => (
                                                <TableRow key={listing._id}>
                                                    <TableCell>
                                                        <Box>
                                                            {listing.seller}
                                                            {listing.icmRegistered && (
                                                                <Chip
                                                                    label="ICM registered"
                                                                    size="small"
                                                                    color="primary"
                                                                    variant="outlined"
                                                                    sx={{ ml: 0.5, mt: 0.5 }}
                                                                />
                                                            )}
          </Box>
                                                    </TableCell>
                                                    <TableCell>
                                                        {listing.name || 'Offset project'}
                                                        {listing.icmPortalProjectUrl && (
                                                            <Typography variant="caption" display="block">
                                                                <Link
                                                                    href={listing.icmPortalProjectUrl}
                                                                    target="_blank"
                                                                    rel="noopener noreferrer"
                                                                >
                                                                    View on ICM portal
                                                                </Link>
                                                            </Typography>
                                                        )}
                                                    </TableCell>
                                                    <TableCell>{formatLocation(listing.location)}</TableCell>
                                                    <TableCell align="right">{listing.credits.toFixed(2)}</TableCell>
                                                    <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>${listing.pricePerCredit.toFixed(2)}/t</TableCell>
                                                    <TableCell>
                                                        <Chip
                                                            label={listing.status}
                                                            color={listing.status === 'active' ? 'success' : 'default'}
                                                            size="small"
                                                        />
                                                    </TableCell>
                                                    <TableCell align="right">
                                                        <Button
                                                            size="small"
                                                            variant="contained"
                                                            onClick={() => openBuyDialog(listing)}
                                                            disabled={listing.status !== 'active'}
                                                        >
                                                            Buy
                                                        </Button>
                                                    </TableCell>
                                                </TableRow>
                                            ))
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        )}
        </CardContent>
      </Card>
            )}
            </Box>

            <Box
                role="tabpanel"
                id="carbon-marketplace-panel-1"
                aria-labelledby="carbon-marketplace-tab-1"
                hidden={tabValue !== 1}
            >
            {tabValue === 1 && (
                <Grid container spacing={3}>
                    <Grid item xs={12} md={6}>
    <Card>
      <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Purchased offset portfolio
                                </Typography>
                                <Typography variant="body2" color="text.secondary" paragraph>
                                    Credits bought from third-party offset projects in the catalog.
                                </Typography>
                                <Divider sx={{ my: 2 }} />
                                <Typography sx={{ whiteSpace: 'nowrap' }}>Total held: {confirmedTons(portfolioStatus, wallet.purchasedTotal)}</Typography>
                                <Typography sx={{ whiteSpace: 'nowrap' }}>Available: {confirmedTons(portfolioStatus, wallet.purchasedAvailable)}</Typography>
                                <Typography sx={{ whiteSpace: 'nowrap' }}>Retired: {confirmedTons(portfolioStatus, wallet.purchasedRetired)}</Typography>
      </CardContent>
    </Card>
                    </Grid>
                    <Grid item xs={12} md={6}>
      <Card>
        <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Earned ICM pool credits
                                </Typography>
                                <Typography variant="body2" color="text.secondary" paragraph>
                                    Credits allocated from aggregated MSME reductions in the Indian Carbon Market pool.
                                </Typography>
                                <Divider sx={{ my: 2 }} />
                                <Typography sx={{ whiteSpace: 'nowrap' }}>Allocated: {confirmedTons(earnedStatus, wallet.earnedAllocated)}</Typography>
                                <Typography sx={{ whiteSpace: 'nowrap' }}>Available: {confirmedTons(earnedStatus, wallet.earnedAvailable)}</Typography>
                                <Typography sx={{ whiteSpace: 'nowrap' }}>Retired: {confirmedTons(earnedStatus, wallet.earnedRetired)}</Typography>
                                <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1, whiteSpace: 'nowrap' }}>
                                    {poolPriceStatus === 'ready'
                                        ? `Indicative pool price: $${wallet.poolPricePerCredit.toFixed(2)} per credit`
                                        : poolPriceStatus === 'error'
                                            ? 'Indicative pool price unavailable'
                                            : 'Loading pool price'}
                                </Typography>
        </CardContent>
      </Card>
                    </Grid>
                </Grid>
            )}
            </Box>

            <Box
                role="tabpanel"
                id="carbon-marketplace-panel-2"
                aria-labelledby="carbon-marketplace-tab-2"
                hidden={tabValue !== 2}
            >
            {tabValue === 2 && (
      <Card>
        <CardContent>
                        <Typography variant="h6" gutterBottom>
                            Project catalog price trends
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                            Average catalog price per tonne, grouped by the date each project was added.
                        </Typography>
                        {listingsStatus === 'loading' ? (
                            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                                <CircularProgress aria-label="Loading project price trends" />
                            </Box>
                        ) : listingsStatus === 'error' ? (
                            <Alert severity="error">
                                Price trends could not be displayed because project prices could not be loaded.
                                {listingsError ? ` ${listingsError}` : ''}
                            </Alert>
                        ) : priceHistory.length === 0 ? (
                            <Alert severity="info">
                                Price trends cannot be displayed because the catalog has no available project price data.
                            </Alert>
                        ) : (
                        <Box sx={{ height: 400, width: '100%', minWidth: 0 }}>
                            <ResponsiveContainer width="100%" height="100%">
                                <ComposedChart data={priceHistory} margin={{ top: 8, right: 16, left: 16, bottom: 8 }}>
                                    <defs>
                                        <linearGradient id="carbonPriceFill" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="0%" stopColor="#2563eb" stopOpacity={0.35} />
                                            <stop offset="100%" stopColor="#2563eb" stopOpacity={0.02} />
                                        </linearGradient>
                                    </defs>
                                    <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                                    <XAxis dataKey="date" tick={tickStyle} interval="preserveStartEnd" />
                                    <YAxis
                                        tick={tickStyle}
                                        width={64}
                                        label={{
                                            value: '$/t',
                                            angle: -90,
                                            position: 'insideLeft',
                                            style: { textAnchor: 'middle', fill: tickStyle.fill, fontSize: 11 },
                                        }}
                                    />
                                    <Tooltip {...tipProps} />
                                    <Legend
                                        {...rechartsLegendProps}
                                        payload={[{
                                            value: 'Price ($/t)',
                                            type: 'line',
                                            id: 'price',
                                            color: '#1d4ed8',
                                        }]}
                                    />
                                    <Area
                                        type="monotone"
                                        dataKey="price"
                                        name="Price ($/t)"
                                        fill="url(#carbonPriceFill)"
                                        stroke="none"
                                        legendType="none"
                                        tooltipType="none"
                                        {...chartAnimationProps}
                                    />
                                    <Line
                                        type="monotone"
                                        dataKey="price"
                                        stroke="#1d4ed8"
                                        strokeWidth={2.5}
                                        dot={priceHistory.length < 2 ? { r: 5, strokeWidth: 0 } : false}
                                        activeDot={{ r: 6, strokeWidth: 0 }}
                                        name="Price ($/t)"
                                        {...chartAnimationProps}
                                    />
                                </ComposedChart>
                            </ResponsiveContainer>
                        </Box>
                        )}
        </CardContent>
      </Card>
            )}
            </Box>

            <Box
                role="tabpanel"
                id="carbon-marketplace-panel-3"
                aria-labelledby="carbon-marketplace-tab-3"
                hidden={tabValue !== 3}
            >
            {tabValue === 3 && (
    <Card>
      <CardContent>
                        <Typography variant="h6" gutterBottom>
                            Combined activity history
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                            Latest 50 offset entries and latest 50 pool entries.
                        </Typography>
                        {historyStatus === 'idle' || historyStatus === 'loading' ? (
                            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                                <CircularProgress aria-label="Loading trade history" />
                            </Box>
                        ) : (
                        <>
                        {historyError && (
                            <Alert severity="error" sx={{ mb: 2 }}>
                                {historyError}
                            </Alert>
                        )}
                        {!(historyStatus === 'error' && tradeHistory.length === 0) && (
                        <TableContainer>
                            <Table>
                                <TableHead>
                                    <TableRow>
                                        <TableCell>Date</TableCell>
                                        <TableCell>Source</TableCell>
                                        <TableCell>Type</TableCell>
                                        <TableCell align="right">Credits (t)</TableCell>
                                        <TableCell align="right">Price</TableCell>
                                        <TableCell>Status</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {historyStatus === 'ready' && tradeHistory.length === 0 ? (
                                        <TableRow>
                                            <TableCell colSpan={6} align="center">
                                                No activity yet
                                            </TableCell>
                                        </TableRow>
                                    ) : tradeHistory.length === 0 ? null : (
                                        tradeHistory.map((trade) => (
                                            <TableRow key={trade._id}>
                                                <TableCell>
                                                    {new Date(trade.createdAt).toLocaleDateString()}
                                                </TableCell>
                                                <TableCell>
                                                    <Chip
                                                        size="small"
                                                        label={trade.source === 'pool' ? 'ICM pool' : 'Offset project'}
                                                        variant="outlined"
                                                    />
                                                </TableCell>
                                                <TableCell>
                                                    <Chip
                                                        label={trade.type.toUpperCase()}
                                                        color={trade.type === 'purchase' ? 'primary' : 'secondary'}
                                                        size="small"
                                                    />
                                                </TableCell>
                                                <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>{trade.credits.toFixed(2)} t</TableCell>
                                                <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>
                                                    {trade.source === 'pool'
                                                        ? `$${trade.pricePerCredit.toFixed(2)}/credit`
                                                        : `$${trade.pricePerCredit.toFixed(2)}/t`}
                                                </TableCell>
                                                <TableCell>
                                                    <Chip
                                                        label={trade.status}
                                                        color={trade.status === 'completed' ? 'success' : 'default'}
                                                        size="small"
                                                    />
                                                </TableCell>
                                            </TableRow>
                                        ))
                                    )}
                                </TableBody>
                            </Table>
                        </TableContainer>
                        )}
                        </>
                        )}
      </CardContent>
    </Card>
            )}
            </Box>

            <Dialog open={buyDialogOpen} onClose={() => setBuyDialogOpen(false)} maxWidth="sm" fullWidth>
                <DialogTitle>Buy offset credits</DialogTitle>
                <DialogContent>
                    {selectedListing ? (
                        <Box sx={{ pt: 2 }}>
                            <Typography variant="subtitle2" gutterBottom>
                                {selectedListing.name}
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                Available: <strong>{selectedListing.credits.toFixed(2)} t</strong>
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                                Price: <strong>${selectedListing.pricePerCredit.toFixed(2)} / t</strong>
                            </Typography>
                            <TextField
                                fullWidth
                                label="Tonnes to purchase"
                                type="number"
                                value={buyAmount}
                                onChange={(e) => setBuyAmount(e.target.value)}
                                margin="normal"
                                inputProps={{ min: 0, max: selectedListing.credits, step: 0.01 }}
                            />
                            {buyAmount && (
                                <Typography variant="h6" sx={{ mt: 2 }}>
                                    Total: ${(parseFloat(buyAmount) * selectedListing.pricePerCredit).toFixed(2)}
                                </Typography>
                            )}
                        </Box>
                    ) : (
                        <Typography variant="body2" sx={{ pt: 2 }}>
                            Select a project from the catalog tab to purchase credits.
                        </Typography>
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setBuyDialogOpen(false)}>Cancel</Button>
                    <Button
                        onClick={handleBuyCredits}
                        variant="contained"
                        disabled={!selectedListing || !buyAmount || loading}
                    >
                        {loading ? <CircularProgress size={16} sx={{ mr: 1 }} aria-hidden /> : null}
                        Buy
                    </Button>
                </DialogActions>
            </Dialog>

            <Dialog open={retireDialogOpen} onClose={() => setRetireDialogOpen(false)} maxWidth="sm" fullWidth>
                <DialogTitle>Retire carbon credits</DialogTitle>
                <DialogContent>
                    <Box sx={{ pt: 2 }}>
                        <FormControl fullWidth margin="normal">
                            <InputLabel id="retire-source-label">Credit source</InputLabel>
                            <Select
                                labelId="retire-source-label"
                                label="Credit source"
                                value={retireSource}
                                onChange={(e) => setRetireSource(e.target.value as RetireCreditSource)}
                            >
                                <MenuItem value="purchased" disabled={portfolioStatus !== 'ready'}>
                                    Purchased offsets ({portfolioStatus === 'ready' ? `${wallet.purchasedAvailable.toFixed(2)} t available` : 'unavailable'})
                                </MenuItem>
                                <MenuItem value="earned" disabled={earnedStatus !== 'ready'}>
                                    Earned ICM pool ({earnedStatus === 'ready' ? `${wallet.earnedAvailable.toFixed(2)} t available` : 'unavailable'})
                                </MenuItem>
                            </Select>
                        </FormControl>
                        <TextField
                            fullWidth
                            label="Tonnes to retire"
                            type="number"
                            value={retireAmount}
                            onChange={(e) => setRetireAmount(e.target.value)}
                            margin="normal"
                            inputProps={{
                                min: 0,
                                max: retireSource === 'purchased' ? wallet.purchasedAvailable : wallet.earnedAvailable,
                                step: 0.01,
                            }}
                        />
                        <TextField
                            fullWidth
                            label="Retirement reason"
                            value={retireReason}
                            onChange={(e) => setRetireReason(e.target.value)}
                            margin="normal"
                            placeholder="e.g. Offset Q1 2026 operational footprint"
                        />
                    </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setRetireDialogOpen(false)}>Cancel</Button>
                    <Button
                        onClick={handleRetireCredits}
                        variant="contained"
                        disabled={!retireAmount || loading || (retireSource === 'purchased' ? portfolioStatus !== 'ready' : earnedStatus !== 'ready')}
                    >
                        {loading ? <CircularProgress size={24} /> : 'Retire'}
                    </Button>
                </DialogActions>
            </Dialog>

            <Dialog open={transferDialogOpen} onClose={() => setTransferDialogOpen(false)} maxWidth="sm" fullWidth>
                <DialogTitle>Transfer earned pool credits</DialogTitle>
                <DialogContent>
                    <Box sx={{ pt: 2 }}>
                        <Typography variant="body2" gutterBottom>
                            Available earned credits: <strong>{wallet.earnedAvailable.toFixed(2)} t</strong>
                        </Typography>
                        <TextField
                            fullWidth
                            label="Recipient MSME ID"
                            value={transferRecipientId}
                            onChange={(e) => setTransferRecipientId(e.target.value)}
                            margin="normal"
                        />
                        <TextField
                            fullWidth
                            label="Tonnes to transfer"
                            type="number"
                            value={transferAmount}
                            onChange={(e) => setTransferAmount(e.target.value)}
                            margin="normal"
                            inputProps={{ min: 0, max: wallet.earnedAvailable, step: 0.01 }}
                        />
                        <TextField
                            fullWidth
                            label="Description (optional)"
                            value={transferDescription}
                            onChange={(e) => setTransferDescription(e.target.value)}
                            margin="normal"
                        />
      </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setTransferDialogOpen(false)}>Cancel</Button>
                    <Button
                        onClick={handleTransferCredits}
                        variant="contained"
                        disabled={!transferAmount || !transferRecipientId || loading}
                    >
                        {loading ? <CircularProgress size={24} /> : 'Transfer'}
                    </Button>
                </DialogActions>
            </Dialog>
    </Box>
  );
};

export default CarbonTrading;
