/** Official Indian Carbon Market portal (Bureau of Energy Efficiency). */
export const ICM_PORTAL_BASE_URL = 'https://indiancarbonmarket.gov.in';

export const ICM_PORTAL_PATHS = {
  home: '/',
  msme: '/msme',
  projects: '/projects',
  registry: '/registry',
  trading: '/trading',
  methodologies: '/methodologies',
} as const;

export type IcmPortalPathKey = keyof typeof ICM_PORTAL_PATHS;

export const buildIcmPortalUrl = (
  pathKey: IcmPortalPathKey = 'home',
  query?: Record<string, string | undefined>
): string => {
  const path = ICM_PORTAL_PATHS[pathKey] ?? ICM_PORTAL_PATHS.home;
  const url = new URL(path, `${ICM_PORTAL_BASE_URL}/`);
  if (query) {
    Object.entries(query).forEach(([key, value]) => {
      if (value?.trim()) {
        url.searchParams.set(key, value);
      }
    });
  }
  return url.toString();
};

export interface IcmPortalLink {
  id: string;
  label: string;
  description: string;
  url: string;
}

